files.content:
:root {
  --bg: #1a1c2c;
  --card: #2a2d4a;
  --primary: #f4d03f;
  --secondary: #5d8aa8;
  --text: #e0e0e0;
  --border: #f4d03f;
  --shadow: #0f0f1a;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Courier New', Courier, monospace;
  font-size: 16px;
  background: var(--bg);
  background-image: linear-gradient(45deg, #1a1c2c 25%, #1e2030 25%, #1e2030 50%, #1a1c2c 50%, #1a1c2c 75%, #1e2030 75%, #1e2030 100%);
  background-size: 40px 40px;
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card);
  border: 4px solid var(--border);
  box-shadow: 8px 8px 0 var(--shadow);
  padding: 24px;
  width: 100%;
  max-width: 420px;
}

h1 {
  font-size: 28px;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--primary);
  text-align: center;
  margin-bottom: 24px;
  text-shadow: 2px 2px 0 var(--shadow);
}

.field {
  margin-bottom: 20px;
}

label, #tip-label {
  display: block;
  margin-bottom: 8px;
  font-size: 16px;
  font-weight: bold;
  color: var(--primary);
  text-transform: uppercase;
  letter-spacing: 1px;
}

input[type="number"] {
  width: 100%;
  padding: 12px;
  font-family: inherit;
  font-size: 18px;
  background: var(--bg);
  color: var(--text);
  border: 3px solid var(--secondary);
  outline: none;
  transition: border-color 0.1s, box-shadow 0.1s;
}

input[type="number"]:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(244, 208, 63, 0.3);
}

input[type="number"]:hover {
  border-color: var(--primary);
}

.tip-buttons {
  display: flex;
  gap: 12px;
}

.tip-btn {
  flex: 1;
  padding: 12px 0;
  font-family: inherit;
  font-size: 18px;
  font-weight: bold;
  background: var(--bg);
  color: var(--text);
  border: 3px solid var(--secondary);
  cursor: pointer;
  transition: all 0.1s;
  text-transform: uppercase;
}

.tip-btn:hover {
  background: var(--secondary);
  color: var(--bg);
  border-color: var(--primary);
}

.tip-btn:focus-visible {
  outline: 3px solid var(--primary);
  outline-offset: 2px;
}

.tip-btn[aria-pressed="true"] {
  background: var(--primary);
  color: var(--bg);
  border-color: var(--primary);
  box-shadow: inset 0 0 0 3px var(--bg);
}

.tip-btn:active {
  transform: translate(2px, 2px);
  box-shadow: none;
}

.results {
  margin-top: 28px;
  border-top: 3px solid var(--secondary);
  padding-top: 20px;
}

.result-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 0;
  font-size: 18px;
}

.result-row:first-child {
  border-bottom: 2px dashed var(--secondary);
}

.result-label {
  color: var(--text);
}

.result-value {
  font-weight: bold;
  color: var(--primary);
  font-size: 20px;
}

@media (max-width: 360px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 24px;
  }
  .tip-buttons {
    gap: 8px;
  }
  .tip-btn {
    font-size: 16px;
    padding: 10px 0;
  }
}

(function() {
  const billInput = document.getElementById('bill');
  const peopleInput = document.getElementById('people');
  const tipButtons = document.querySelectorAll('.tip-btn');
  const tipPerPersonEl = document.getElementById('tip-per-person');
  const totalPerPersonEl = document.getElementById('total-per-person');

  let selectedTip = 0;

  function formatCurrency(value) {
    return '$' + value.toFixed(2);
  }

  function calculate() {
    const bill = parseFloat(billInput.value) || 0;
    const people = parseInt(peopleInput.value, 10) || 1;
    const safePeople = people < 1 ? 1 : people;
    const tipAmount = bill * (selectedTip / 100);
    const total = bill + tipAmount;
    const tipPerPerson = tipAmount / safePeople;
    const totalPerPerson = total / safePeople;

    tipPerPersonEl.textContent = formatCurrency(tipPerPerson);
    totalPerPersonEl.textContent = formatCurrency(totalPerPerson);
  }

  tipButtons.forEach(function(btn) {
    btn.addEventListener('click', function() {
      const tipValue = parseInt(btn.dataset.tip, 10);
      if (selectedTip === tipValue) {
        selectedTip = 0;
        btn.setAttribute('aria-pressed', 'false');
      } else {
        selectedTip = tipValue;
        tipButtons.forEach(function(b) {
          b.setAttribute('aria-pressed', 'false');
        });
        btn.setAttribute('aria-pressed', 'true');
      }
      calculate();
    });
  });

  billInput.addEventListener('input', calculate);
  peopleInput.addEventListener('input', calculate);

  calculate();
})();
